const input = $input.first().json;

// Extract text from Gemini response
let text = '';
try {
  text = input.candidates?.[0]?.content?.parts?.[0]?.text || '';
} catch (e) {
  return [{
    json: {
      error: 'Failed to get Gemini response',
      raw: JSON.stringify(input).substring(0, 500),
    },
  }];
}

// Clean and parse JSON
try {
  text = text
    .replace(/```json\n?/g, '')
    .replace(/```\n?/g, '')
    .trim();
  const parsed = JSON.parse(text);

  // Validate structure: must have 6 prompts
  if (
    !parsed.prompts ||
    !Array.isArray(parsed.prompts) ||
    parsed.prompts.length !== 6
  ) {
    throw new Error('Invalid prompts structure (need 6 prompts)');
  }

  return [{
    json: {
      ...parsed,
      type: 'morning',
      success: true,
    },
  }];
} catch (e) {
  // Fallback prompts using the 6-section master framework
  return [{
    json: {
      type: 'morning',
      success: false,
      theme: 'Master Reset',
      trend_insight: 'AI parsing failed - using default 6-section master prompts',
      prompts: [
        {
          category: 'foundation',
          prompt: 'What is my one Definite Chief Aim today, and where do I feel genuine burning desire versus just a weak wish?',
          why: 'Return to a single clear aim and desire',
        },
        {
          category: 'execution',
          prompt: 'Where am I secretly blaming others today for something that is 100% my responsibility, and what 20% of work will drive 80% of my results?',
          why: 'Shift from blame to ownership and essentialism',
        },
        {
          category: 'system',
          prompt: 'What specific cue, routine, and reward am I reinforcing today, and what one sentence of auto-suggestion will I repeat to my subconscious?',
          why: 'Lock in one clear habit loop and inner script',
        },
        {
          category: 'edge',
          prompt: 'What uncomfortable “No” or honest conversation am I avoiding today, and how can I use tactical empathy to listen for what isn’t being said?',
          why: 'Lean into rejection/discomfort for growth',
        },
        {
          category: 'evolution',
          prompt: 'Looking at my current obstacles, where is antifragility being built and where am I just getting tired, and what specialized knowledge or Master Mind support do I actually need?',
          why: 'Reframe setbacks and identify missing knowledge',
        },
        {
          category: 'output',
          prompt: 'Am I generating the energy required to lead today, and what one bold move—if I actually did it—would make most other tasks easier or irrelevant?',
          why: 'Drive toward bold, high-leverage action',
        },
      ],
      affirmation:
        'I move with radical ownership, focused desire, and bold energy toward my chief aim today.',
    },
  }];
}

