// Merge past journals and goals into a clean context object
const items = $input.all();
const journals = items[0]?.json?.results || [];
const goals = items.length > 1 ? (items[1]?.json?.results || []) : [];

// Extract readable journal data
const journalSummary = journals.slice(0, 14).map(j => {
  const props = j.properties || {};
  return {
    date: props.Date?.date?.start || 'unknown',
    theme: props.Theme?.rich_text?.[0]?.text?.content || '',
    responses: props.Responses?.rich_text?.[0]?.text?.content || props.Content?.rich_text?.[0]?.text?.content || '',
    mood: props.Mood?.select?.name || props.Mood?.number || '',
    status: props.Status?.select?.name || ''
  };
}).filter(j => j.date !== 'unknown');

// Extract goals
const goalSummary = goals.map(g => {
  const props = g.properties || {};
  return {
goal: props.Title?.title?.[0]?.text?.content || '',
category: props.Type?.select?.name || '',
progress: props['Progress %']?.formula?.number || 0,
status: props.Type?.select?.name || ''
  };
});

return [{
  json: {
    journals: journalSummary,
    goals: goalSummary,
    today: new Date().toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' }),
    dayOfWeek: new Date().toLocaleDateString('en-US', { weekday: 'long' })
  }
}];

const inputs = $input.all();

const nightResults = inputs[0] && inputs[0].json && inputs[0].json.results ? inputs[0].json.results : [];
const morningResults = inputs[1] && inputs[1].json && inputs[1].json.results ? inputs[1].json.results : [];
const morningEntry = morningResults.length > 0 ? morningResults[0] : null;

const journals = nightResults.slice(0, 14).map(function(j) {
  const props = j.properties || {};
  return {
    date: props.Date && props.Date.date ? props.Date.date.start : 'unknown',
    theme: props.Theme && props.Theme.rich_text && props.Theme.rich_text[0] ? props.Theme.rich_text[0].text.content : '',
    responses: (props.Responses && props.Responses.rich_text && props.Responses.rich_text[0] ? props.Responses.rich_text[0].text.content : '') || (props.Content && props.Content.rich_text && props.Content.rich_text[0] ? props.Content.rich_text[0].text.content : ''),
    mood: (props.Mood && props.Mood.select ? props.Mood.select.name : '') || (props.Mood && props.Mood.number ? props.Mood.number : '')
  };
}).filter(function(j) { return j.date !== 'unknown'; });

let todayMorning = null;
if (morningEntry) {
  const props = morningEntry.properties || {};
  todayMorning = {
    date: props.Date && props.Date.date ? props.Date.date.start : '',
    theme: props.Theme && props.Theme.rich_text && props.Theme.rich_text[0] ? props.Theme.rich_text[0].text.content : '',
    responses: (props.Responses && props.Responses.rich_text && props.Responses.rich_text[0] ? props.Responses.rich_text[0].text.content : '') || (props.Content && props.Content.rich_text && props.Content.rich_text[0] ? props.Content.rich_text[0].text.content : '')
  };
}

return [{
  json: {
    journals: journals,
    todayMorning: todayMorning,
    today: new Date().toLocaleDateString('en-US', {
      weekday: 'long', year: 'numeric', month: 'long', day: 'numeric'
    })
  }
}];

